'use client';

import { ChangeEvent, useEffect, useMemo, useState, useTransition } from 'react';
import { ProductFiscalEditor } from './product-fiscal-editor';
import { RTC_CST_OPTIONS } from '../../../lib/fiscal/rtc-tax-table';
import {
  productStudioAddStock,
  productStudioBarcode,
  productStudioBulkUpdate,
  productStudioCompositionSet,
  productStudioDetail,
  productStudioFilteredIds,
  productStudioList,
  productStudioSave,
  productStudioSetActive,
  type ProductListFilters,
} from './product-studio-actions';

type Row=Record<string,unknown>;
type PurchaseUnit={unit:string;conversion_factor:number;barcode:string;is_default:boolean};
type CompositionItem={component_product_id:string;quantity:number;unit:string;waste_percent:number;deduct_stock:boolean;notes?:string};
type GradeAttribute={name:string;values:string[]};
type VariantDraft={id:string;product_code:string;sku:string;label:string;attributes:Record<string,string>;barcode:string;cost_price:string;sale_price:string;minimum_stock:string;stock_to_add:string;stock:number;active:boolean;image_url:string};
type AdvancedTab='operation'|'fiscal'|'stock'|'composition'|'history';

const units=[['UN','Unidade'],['KG','Quilograma'],['CX','Caixa'],['PC','Peça'],['PCT','Pacote'],['FD','Fardo'],['LT','Litro'],['ML','Mililitro'],['G','Grama'],['M','Metro'],['M2','Metro²'],['M3','Metro cúbico'],['DZ','Dúzia'],['BD','Balde'],['SC','Saco'],['RL','Rolo']] as const;
const productTypes=[['fixed_asset','Ativo imobilizado'],['packaging','Embalagem'],['use_consumption','Material de uso e consumo'],['raw_material','Matéria-prima'],['resale','Mercadoria para revenda'],['other','Outras'],['other_inputs','Outros insumos'],['finished_product','Produto acabado'],['work_in_process','Produto em processo'],['intermediate_product','Produto intermediário'],['service','Serviços'],['byproduct','Subproduto']] as const;
const text=(v:unknown)=>v==null?'':String(v);
const num=(v:unknown)=>Number(v||0)||0;
const bool=(v:unknown,fallback=false)=>v==null?fallback:Boolean(v);
const rows=(v:unknown):Row[]=>Array.isArray(v)?v as Row[]:[];
const obj=(v:unknown):Row=>v&&typeof v==='object'&&!Array.isArray(v)?v as Row:{};
const money=(v:unknown)=>num(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const productTypeLabel=(v:unknown)=>productTypes.find(([code])=>code===text(v))?.[1]||'Mercadoria para revenda';

const icmsTaxOptions=[['00','Tributada integralmente'],['10','Tributada + ST'],['20','Redução de base'],['30','Isenta/não tributada + ST'],['40','Isenta'],['41','Não tributada'],['50','Suspensão'],['51','Diferimento'],['60','ICMS cobrado anteriormente por ST'],['70','Redução de base + ST'],['90','Outras']] as const;
const csosnTaxOptions=[['101','Tributada com permissão de crédito'],['102','Tributada sem permissão de crédito'],['103','Isenção por faixa de receita'],['201','Crédito + ST'],['202','Sem crédito + ST'],['203','Isenção + ST'],['300','Imune'],['400','Não tributada'],['500','ICMS cobrado anteriormente por ST/antecipação'],['900','Outros']] as const;
const taxOptions=[
  ...RTC_CST_OPTIONS.map(o=>({value:`reform:${o.code}`,label:`IBS/CBS ${o.code} - ${o.label}`})),
  ...csosnTaxOptions.map(([code,label])=>({value:`csosn:${code}`,label:`CSOSN ${code} - ${label}`})),
  ...icmsTaxOptions.map(([code,label])=>({value:`cst:${code}`,label:`CST ICMS ${code} - ${label}`})),
];
const taxLabel=(row:Row)=>{const key=text(row.tax_situation);if(!key)return '—';return taxOptions.find(o=>o.value===key)?.label||key.replace('reform:','IBS/CBS ').replace('csosn:','CSOSN ').replace('cst:','CST ICMS ');};

function blank(){return {
  id:'',product_code:'',sku:'',barcode:'',name:'',description:'',group_id:'',class_id:'',unit:'UN',product_type:'resale',product_structure:'simple',active:true,is_weighable:false,
  supplier_id:'',exclusive_supplier:false,financial_category:'',stock_location:'',fractioned:false,prompt_quantity:false,modifiers_enabled:false,allow_discount:true,apply_surcharge:true,
  self_service:false,favorite:false,age_restricted:false,label_scale:false,shelf_life_days:'0',ncm:'',cest:'',cfop_default:'',origin:'0',cost_price:'0',sale_price:'0',minimum_stock:'0',stock_to_add:'',
  production_mode:'stock',production_yield:'1',production_printer:'',production_sector:'',auto_print_production:true,production_description:'',image_url:'',menu_image_url:'',self_service_image_url:'',menu_description:'',
  cst_icms:'',csosn:'',cst_pis:'',cst_cofins:'',cst_ipi:'',icms_rate:'',pis_rate:'',cofins_rate:'',ipi_rate:'',reform_cst:'',reform_classification:'',fiscal_origin_uf:'',fiscal_destination_uf:'',fiscal_customer_type:'both',
  icms_tax_benefit:'',icms_exemption_reason:'',icms_discount:false,icms_credit_benefit:'',icms_presumed_credit_rate:'',ipi_legal_framework:'',petroleum_anp_code:'',petroleum_cide_rate:'',petroleum_mix_percent:'',
};}
type Draft=ReturnType<typeof blank>;

async function imageData(e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return '';if(file.size>350_000)throw new Error('Imagem acima de 350 KB. Reduza o arquivo.');return await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Falha ao ler a imagem.'));reader.readAsDataURL(file);});}

function draftFromDetail(detail:Row):Draft{
  const p=obj(detail.product);const fp=obj(p.fiscal_profile);const barcodes=rows(detail.barcodes);
  return {...blank(),id:text(p.id),product_code:text(p.product_code),sku:text(p.sku),barcode:text(barcodes.find(b=>b.is_primary)?.barcode||barcodes[0]?.barcode),name:text(p.name),description:text(p.description),group_id:text(p.group_id),class_id:text(p.class_id),unit:text(p.unit)||'UN',product_type:text(p.product_type)||'resale',product_structure:text(p.product_structure)||'simple',active:p.active!==false,is_weighable:bool(p.is_weighable),supplier_id:text(p.supplier_id),exclusive_supplier:bool(p.exclusive_supplier),financial_category:text(p.financial_category),stock_location:text(p.stock_location),fractioned:bool(p.fractioned),prompt_quantity:bool(p.prompt_quantity),modifiers_enabled:bool(p.modifiers_enabled),allow_discount:bool(p.allow_discount,true),apply_surcharge:bool(p.apply_surcharge,true),self_service:bool(p.self_service),favorite:bool(p.favorite),age_restricted:bool(p.age_restricted),label_scale:bool(p.label_scale),shelf_life_days:text(p.shelf_life_days||0),ncm:text(p.ncm),cest:text(p.cest),cfop_default:text(p.cfop_default),origin:text(p.origin||0),cost_price:text(p.cost_price||0),sale_price:text(p.sale_price||0),minimum_stock:text(p.minimum_stock||0),stock_to_add:'',production_mode:text(p.production_mode)||'stock',production_yield:text(p.production_yield||1),production_printer:text(p.production_printer),production_sector:text(p.production_sector),auto_print_production:bool(p.auto_print_production,true),production_description:text(p.production_description),image_url:text(p.image_url),menu_image_url:text(p.menu_image_url),self_service_image_url:text(p.self_service_image_url),menu_description:text(p.menu_description),cst_icms:text(fp.cst_icms),csosn:text(fp.csosn),cst_pis:text(fp.cst_pis),cst_cofins:text(fp.cst_cofins),cst_ipi:text(fp.cst_ipi),icms_rate:text(fp.icms_rate),pis_rate:text(fp.pis_rate),cofins_rate:text(fp.cofins_rate),ipi_rate:text(fp.ipi_rate),reform_cst:text(fp.reform_cst),reform_classification:text(fp.reform_classification),fiscal_origin_uf:text(fp.fiscal_origin_uf),fiscal_destination_uf:text(fp.fiscal_destination_uf),fiscal_customer_type:text(fp.fiscal_customer_type)||'both',icms_tax_benefit:text(fp.icms_tax_benefit),icms_exemption_reason:text(fp.icms_exemption_reason),icms_discount:bool(fp.icms_discount),icms_credit_benefit:text(fp.icms_credit_benefit),icms_presumed_credit_rate:text(fp.icms_presumed_credit_rate),ipi_legal_framework:text(fp.ipi_legal_framework),petroleum_anp_code:text(fp.petroleum_anp_code),petroleum_cide_rate:text(fp.petroleum_cide_rate),petroleum_mix_percent:text(fp.petroleum_mix_percent)};
}

function variantFromRow(row:Row):VariantDraft{return {id:text(row.id),product_code:text(row.product_code),sku:text(row.sku),label:text(row.variant_label),attributes:obj(row.variant_attributes) as Record<string,string>,barcode:text(row.barcode),cost_price:text(row.cost_price||0),sale_price:text(row.sale_price||0),minimum_stock:text(row.minimum_stock||0),stock_to_add:'',stock:num(row.stock),active:row.active!==false,image_url:text(row.image_url)};}
function variantKey(attrs:Record<string,string>){return Object.keys(attrs).sort().map(k=>`${k}:${attrs[k]}`).join('|');}
function combinations(attributes:GradeAttribute[]){const valid=attributes.filter(a=>a.name.trim()&&a.values.length);if(!valid.length)return [] as Record<string,string>[];return valid.reduce<Record<string,string>[]>((acc,attr)=>acc.flatMap(base=>attr.values.map(value=>({...base,[attr.name.trim()]:value}))),[{}]);}

function Toggle({value,onChange,disabled=false,label}:{value:boolean;onChange:(v:boolean)=>void;disabled?:boolean;label?:string}){return <button type="button" disabled={disabled} className={`studio-switch ${value?'on':''}`} onClick={()=>onChange(!value)} aria-pressed={value}><span/><b>{label??(value?'Sim':'Não')}</b></button>}
function FieldImage({title,value,onChange,main=false}:{title:string;value:string;onChange:(v:string)=>void;main?:boolean}){const [error,setError]=useState('');return <div className={`studio-image-field image-field ${main?'main':''}`}><div className="studio-image-preview">{value?<img src={value} alt={title}/>:<span>Sem imagem</span>}</div><div className="studio-image-meta"><strong>{title}</strong><label>Selecionar<input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{try{setError('');const data=await imageData(e);if(data)onChange(data)}catch(err){setError(err instanceof Error?err.message:String(err))}}}/></label>{value&&<button type="button" onClick={()=>onChange('')}>Remover</button>}</div>{error&&<small>{error}</small>}</div>}
function VariantImage({value,fallback,label,onChange}:{value:string;fallback:string;label:string;onChange:(v:string)=>void}){const [error,setError]=useState('');const preview=value||fallback;return <div className="studio-variant-image image-field"><div className={`studio-variant-thumb ${value?'custom':'inherited'}`}>{preview?<img src={preview} alt={`Foto ${label}`}/>:<span>+</span>}</div><div className="studio-variant-image-actions"><label>{value?'Trocar':'Foto'}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{try{setError('');const data=await imageData(e);if(data)onChange(data)}catch(err){setError(err instanceof Error?err.message:String(err))}}}/></label>{value&&<button type="button" onClick={()=>onChange('')}>Remover</button>}{!value&&fallback&&<small>Usa a principal</small>}{error&&<small className="error">{error}</small>}</div></div>}

function ProductEditor({row,products,groups,classes,suppliers,modifiers,branches,onClose,onSaved}:{row:Row|null;products:Row[];groups:Row[];classes:Row[];suppliers:Row[];modifiers:Row[];branches:Row[];onClose:()=>void;onSaved:()=>Promise<void>}){
  const selectedId=text(row?.id);const [pending,startTransition]=useTransition();const [loaded,setLoaded]=useState(!selectedId);const [message,setMessage]=useState('');const [draft,setDraft]=useState<Draft>(()=>blank());const [gradeAttributes,setGradeAttributes]=useState<GradeAttribute[]>([{name:'Cor',values:[]},{name:'Tamanho',values:[]}]);const [variants,setVariants]=useState<VariantDraft[]>([]);const [purchaseUnits,setPurchaseUnits]=useState<PurchaseUnit[]>([]);const [composition,setComposition]=useState<CompositionItem[]>([]);const [modifierIds,setModifierIds]=useState<string[]>([]);const [stockRows,setStockRows]=useState<Row[]>([]);const [history,setHistory]=useState<Row[]>([]);const [advancedTab,setAdvancedTab]=useState<AdvancedTab>('operation');
  const filteredClasses=useMemo(()=>classes.filter(c=>!draft.group_id||!c.group_id||text(c.group_id)===draft.group_id),[classes,draft.group_id]);const productMap=useMemo(()=>new Map(products.map(p=>[text(p.id),p])),[products]);const set=<K extends keyof Draft>(key:K,value:Draft[K])=>setDraft(current=>({...current,[key]:value}));
  const margin=num(draft.sale_price)>0?((num(draft.sale_price)-num(draft.cost_price))/num(draft.sale_price))*100:0;const compositionCost=composition.reduce((sum,item)=>sum+item.quantity*(1+item.waste_percent/100)*num(productMap.get(item.component_product_id)?.cost_price),0);

  useEffect(()=>{let cancelled=false;setMessage('');setAdvancedTab('operation');if(!selectedId){setDraft(blank());setGradeAttributes([{name:'Cor',values:[]},{name:'Tamanho',values:[]}]);setVariants([]);setPurchaseUnits([]);setComposition([]);setModifierIds([]);setStockRows([]);setHistory([]);setLoaded(true);return()=>{cancelled=true}}setLoaded(false);void(async()=>{const result=await productStudioDetail(selectedId);if(cancelled)return;if(!result.ok){setMessage(`Não foi possível abrir o produto: ${text(result.error)}`);setLoaded(true);return}const detail=obj(result.data);setDraft(draftFromDetail(detail));const attrs=rows(detail.grade_attributes).map(a=>({name:text(a.name),values:Array.isArray(a.values)?a.values.map(text):[]})).filter(a=>a.name);setGradeAttributes(attrs.length?attrs:[{name:'Cor',values:[]},{name:'Tamanho',values:[]}]);setVariants(rows(detail.variants).map(variantFromRow));setPurchaseUnits(rows(detail.purchase_units).map(u=>({unit:text(u.unit)||'UN',conversion_factor:num(u.conversion_factor)||1,barcode:text(u.barcode),is_default:bool(u.is_default)})));setComposition(rows(detail.composition).map(i=>({component_product_id:text(i.component_product_id),quantity:num(i.quantity),unit:text(i.unit)||'UN',waste_percent:num(i.waste_percent),deduct_stock:i.deduct_stock!==false,notes:text(i.notes)})));setModifierIds(rows(detail.modifiers).filter(m=>m.linked).map(m=>text(m.id)));setStockRows(rows(detail.stock));setHistory(rows(detail.history));setLoaded(true)})();return()=>{cancelled=true}},[selectedId]);

  const refreshDetail=async(productId:string)=>{const result=await productStudioDetail(productId);if(!result.ok)return;const detail=obj(result.data);setStockRows(rows(detail.stock));setHistory(rows(detail.history));setVariants(rows(detail.variants).map(variantFromRow));};
  const generateBarcode=()=>startTransition(async()=>{const r=await productStudioBarcode();if(r.ok)set('barcode',text(r.barcode));else setMessage(text(r.error||'Não foi possível gerar o EAN.'));});
  const generateVariants=()=>{const combos=combinations(gradeAttributes);if(!combos.length)return setMessage('Informe pelo menos um atributo com valores antes de gerar as variações.');const existing=new Map(variants.map(v=>[variantKey(v.attributes),v]));setVariants(combos.map(attrs=>{const found=existing.get(variantKey(attrs));return found??{id:'',product_code:'',sku:'',label:Object.values(attrs).join(' • '),attributes:attrs,barcode:'',cost_price:draft.cost_price,sale_price:draft.sale_price,minimum_stock:draft.minimum_stock,stock_to_add:'',stock:0,active:true,image_url:''};}).map(v=>({...v,label:Object.values(v.attributes).join(' • ')})));setMessage(`${combos.length} variação(ões) preparadas.`);};
  const applyDefaults=()=>setVariants(current=>current.map(v=>({...v,cost_price:draft.cost_price,sale_price:draft.sale_price,minimum_stock:draft.minimum_stock})));
  const addGradeValue=(index:number,value:string)=>{const clean=value.trim();if(!clean)return;setGradeAttributes(current=>current.map((a,i)=>i===index&&!a.values.includes(clean)?{...a,values:[...a.values,clean]}:a));};

  const save=()=>startTransition(async()=>{setMessage('');if(!draft.name.trim())return setMessage('Informe a descrição do produto.');if(draft.product_structure==='grade'&&!variants.length)return setMessage('Gere ao menos uma variação para o produto com grade.');const fiscal_profile={cst_icms:draft.cst_icms||null,csosn:draft.csosn||null,cst_pis:draft.cst_pis||null,cst_cofins:draft.cst_cofins||null,cst_ipi:draft.cst_ipi||null,icms_rate:num(draft.icms_rate),pis_rate:num(draft.pis_rate),cofins_rate:num(draft.cofins_rate),ipi_rate:num(draft.ipi_rate),reform_cst:draft.reform_cst||null,reform_classification:draft.reform_classification||null,fiscal_origin_uf:draft.fiscal_origin_uf||null,fiscal_destination_uf:draft.fiscal_destination_uf||null,fiscal_customer_type:draft.fiscal_customer_type||'both',icms_tax_benefit:draft.icms_tax_benefit||null,icms_exemption_reason:draft.icms_exemption_reason||null,icms_discount:Boolean(draft.icms_discount),icms_credit_benefit:draft.icms_credit_benefit||null,icms_presumed_credit_rate:num(draft.icms_presumed_credit_rate),ipi_legal_framework:draft.ipi_legal_framework||null,petroleum_anp_code:draft.petroleum_anp_code||null,petroleum_cide_rate:num(draft.petroleum_cide_rate),petroleum_mix_percent:num(draft.petroleum_mix_percent)};const result=await productStudioSave({...draft,cost_price:num(draft.cost_price),sale_price:num(draft.sale_price),minimum_stock:num(draft.minimum_stock),stock_to_add:draft.product_structure==='simple'?num(draft.stock_to_add):0,shelf_life_days:num(draft.shelf_life_days),production_yield:num(draft.production_yield),purchase_units:purchaseUnits,modifier_ids:modifierIds,fiscal_profile,grade_attributes:gradeAttributes,variants:draft.product_structure==='grade'?variants.map((v,index)=>({...v,sort:index+1,cost_price:num(v.cost_price),sale_price:num(v.sale_price),minimum_stock:num(v.minimum_stock),stock_to_add:num(v.stock_to_add)})):[]});if(!result.ok)return setMessage(`Não foi possível salvar: ${text(result.error)}`);const productId=text(result.id);const comp=await productStudioCompositionSet(productId,composition);if(!comp.ok)return setMessage(`Produto salvo, mas a composição não pôde ser atualizada: ${text(comp.error)}`);setDraft(current=>({...current,id:productId,product_code:text(result.product_code||current.product_code),stock_to_add:''}));await refreshDetail(productId);await onSaved();setMessage(draft.product_structure==='grade'?'Produto com grade salvo. As variações possuem código, preço, estoque e foto próprios.':'Produto simples salvo com sucesso.');});
  const addStock=()=>{if(!draft.id)return setMessage('Salve o produto antes de lançar estoque.');const quantity=num(draft.stock_to_add);if(quantity<=0)return setMessage('Informe uma quantidade maior que zero.');startTransition(async()=>{const r=await productStudioAddStock(draft.id,quantity,num(draft.cost_price));if(!r.ok)return setMessage(text(r.error||'Não foi possível registrar a entrada.'));set('stock_to_add','');await refreshDetail(draft.id);await onSaved();setMessage(`Entrada registrada: +${quantity}.`);});};

  if(!loaded)return <section className="product-studio-card studio-loading">Carregando cadastro completo...</section>;
  return <div className="product-studio-editor">
    <header className="studio-editor-top"><div><button type="button" onClick={onClose}>← Produtos</button><span className="studio-eyebrow">CADASTRO DE PRODUTO</span><h2>{draft.name||'Novo produto'}</h2><p>{draft.id?`Código ${draft.product_code||'—'} • ${productTypeLabel(draft.product_type)}`:'Cadastre produto simples ou crie uma grade completa com variações.'}</p></div><div className="studio-top-actions"><button type="button" className="studio-secondary" onClick={onClose}>Voltar</button><button type="button" className="studio-primary" disabled={pending} onClick={save}>{pending?'Salvando...':'Salvar produto'}</button></div></header>
    {message&&<div className="studio-message">{message}</div>}

    <section className="product-studio-card studio-type-card"><div><strong>Estrutura do produto</strong><span>Escolha como este item será controlado no catálogo e no estoque.</span></div><div className="studio-type-options"><button type="button" className={draft.product_structure==='simple'?'active':''} onClick={()=>set('product_structure','simple')}><b>Produto simples</b><small>Um SKU, um preço e um saldo.</small></button><button type="button" className={draft.product_structure==='grade'?'active':''} onClick={()=>set('product_structure','grade')}><b>Produto com grade</b><small>Cores, tamanhos e outras variações.</small></button></div></section>

    <section className="studio-main-grid"><div className="product-studio-card studio-basic"><div className="studio-section-title"><div><span>Dados principais</span><h3>Identificação do produto</h3></div><Toggle value={draft.active} onChange={v=>set('active',v)} label={draft.active?'Ativo':'Inativo'}/></div><div className="studio-form-grid"><label className="span2">Descrição<input value={draft.name} onChange={e=>set('name',e.target.value)} placeholder="Descrição do produto"/></label><label>Referência / SKU<input value={draft.sku} onChange={e=>set('sku',e.target.value)} placeholder="Automático ou referência interna"/></label><label>Unidade<select value={draft.unit} onChange={e=>set('unit',e.target.value)}>{units.map(([code,label])=><option key={code} value={code}>{code} — {label}</option>)}</select></label><label>Grupo<select value={draft.group_id} onChange={e=>{set('group_id',e.target.value);set('class_id','')}}><option value="">Selecione</option>{groups.map(g=><option key={text(g.id)} value={text(g.id)}>{text(g.name)}</option>)}</select></label><label>Classe<select value={draft.class_id} onChange={e=>set('class_id',e.target.value)}><option value="">Selecione</option>{filteredClasses.map(c=><option key={text(c.id)} value={text(c.id)}>{text(c.name)}</option>)}</select></label><label>Tipo<select value={draft.product_type} onChange={e=>set('product_type',e.target.value)}>{productTypes.map(([code,label])=><option key={code} value={code}>{label}</option>)}</select></label><label>NCM<input value={draft.ncm} onChange={e=>set('ncm',e.target.value)}/></label><label className="span2">EAN / GTIN<div className="studio-inline"><input value={draft.barcode} onChange={e=>set('barcode',e.target.value.replace(/\s/g,''))}/><button type="button" onClick={generateBarcode}>Gerar</button></div></label><label className="span2">Descrição complementar<textarea rows={3} value={draft.description} onChange={e=>set('description',e.target.value)}/></label></div></div><div className="product-studio-card studio-cover"><FieldImage main title="Imagem principal" value={draft.image_url} onChange={value=>set('image_url',value)}/></div></section>

    <section className="product-studio-card studio-prices"><div className="studio-section-title"><div><span>Preços</span><h3>Formação comercial</h3></div>{draft.product_structure==='grade'&&<button type="button" className="studio-secondary" onClick={applyDefaults}>Aplicar às variações</button>}</div><div className="studio-price-grid"><label><span>Preço de compra / custo</span><strong>{money(draft.cost_price)}</strong><input type="number" min="0" step="0.01" value={draft.cost_price} onChange={e=>set('cost_price',e.target.value)}/></label><label><span>Preço de venda</span><strong>{money(draft.sale_price)}</strong><input type="number" min="0" step="0.01" value={draft.sale_price} onChange={e=>set('sale_price',e.target.value)}/></label><article><span>Margem estimada</span><strong>{margin.toLocaleString('pt-BR',{maximumFractionDigits:2})}%</strong><small>Venda menos custo sobre o preço de venda.</small></article><label><span>Estoque mínimo</span><strong>{num(draft.minimum_stock).toLocaleString('pt-BR')}</strong><input type="number" min="0" step="0.001" value={draft.minimum_stock} onChange={e=>set('minimum_stock',e.target.value)}/></label></div></section>

    {draft.product_structure==='grade'&&<section className="product-studio-card studio-grade"><div className="studio-section-title"><div><span>Grade</span><h3>Atributos e variações</h3><p>Monte combinações como Cor × Tamanho. Cada variação terá código, foto, EAN, preço e estoque próprios.</p></div><div><button type="button" className="studio-secondary" onClick={()=>setGradeAttributes(current=>[...current,{name:'Novo atributo',values:[]}])}>+ Atributo</button><button type="button" className="studio-primary" onClick={generateVariants}>Gerar variações</button></div></div><div className="studio-attribute-grid">{gradeAttributes.map((attr,index)=><AttributeEditor key={index} attribute={attr} onName={name=>setGradeAttributes(current=>current.map((a,i)=>i===index?{...a,name}:a))} onAdd={value=>addGradeValue(index,value)} onRemoveValue={value=>setGradeAttributes(current=>current.map((a,i)=>i===index?{...a,values:a.values.filter(v=>v!==value)}:a))} onRemove={()=>setGradeAttributes(current=>current.filter((_,i)=>i!==index))}/>)}</div><div className="studio-variant-head"><strong>{variants.length} variação(ões)</strong><span>A foto pode ser própria por variação; sem foto própria, a variação usa a imagem principal do produto.</span></div><div className="studio-variant-table-wrap"><table className="studio-variant-table"><thead><tr><th>Ativo</th><th>Variação</th><th>Foto</th><th>Código</th><th>SKU</th><th>EAN</th><th>Custo</th><th>Venda</th><th>Saldo</th><th>Entrada</th></tr></thead><tbody>{variants.length===0?<tr><td colSpan={10} className="studio-empty">Defina os atributos e clique em “Gerar variações”.</td></tr>:variants.map((variant,index)=><tr key={variant.id||variantKey(variant.attributes)}><td><Toggle value={variant.active} onChange={active=>setVariants(current=>current.map((v,i)=>i===index?{...v,active}:v))}/></td><td><strong>{variant.label}</strong><small>{Object.entries(variant.attributes).map(([k,v])=>`${k}: ${v}`).join(' · ')}</small></td><td><VariantImage value={variant.image_url} fallback={draft.image_url} label={variant.label} onChange={image_url=>setVariants(current=>current.map((v,i)=>i===index?{...v,image_url}:v))}/></td><td>{variant.product_code||'Novo'}</td><td><input value={variant.sku} onChange={e=>setVariants(current=>current.map((v,i)=>i===index?{...v,sku:e.target.value}:v))}/></td><td><input value={variant.barcode} onChange={e=>setVariants(current=>current.map((v,i)=>i===index?{...v,barcode:e.target.value.replace(/\s/g,'')}:v))}/></td><td><input type="number" min="0" step="0.01" value={variant.cost_price} onChange={e=>setVariants(current=>current.map((v,i)=>i===index?{...v,cost_price:e.target.value}:v))}/></td><td><input type="number" min="0" step="0.01" value={variant.sale_price} onChange={e=>setVariants(current=>current.map((v,i)=>i===index?{...v,sale_price:e.target.value}:v))}/></td><td><b>{variant.stock.toLocaleString('pt-BR',{maximumFractionDigits:3})}</b></td><td><input type="number" min="0" step="0.001" value={variant.stock_to_add} onChange={e=>setVariants(current=>current.map((v,i)=>i===index?{...v,stock_to_add:e.target.value}:v))} placeholder="0"/></td></tr>)}</tbody></table></div></section>}

    <section className="product-studio-card studio-gallery"><div className="studio-section-title"><div><span>Galeria</span><h3>Imagens do produto</h3></div></div><div className="studio-gallery-grid"><FieldImage title="Principal / PDV" value={draft.image_url} onChange={value=>set('image_url',value)}/><FieldImage title="Cardápio" value={draft.menu_image_url} onChange={value=>set('menu_image_url',value)}/><FieldImage title="Autoatendimento" value={draft.self_service_image_url} onChange={value=>set('self_service_image_url',value)}/></div><label className="studio-full-field">Descrição para cardápio / QR Code<input value={draft.menu_description} onChange={e=>set('menu_description',e.target.value)}/></label></section>

    <section className="product-studio-card studio-advanced"><div className="studio-section-title"><div><span>Configurações preservadas</span><h3>Operação, fiscal, estoque e produção</h3></div></div><div className="studio-tabs">{([['operation','Operação'],['fiscal','Fiscal e modificadores'],['stock','Estoque'],['composition','Composição'],['history','Histórico']] as [AdvancedTab,string][]).map(([id,label])=><button type="button" key={id} className={advancedTab===id?'active':''} onClick={()=>setAdvancedTab(id)}>{label}</button>)}</div>
      {advancedTab==='operation'&&<div className="studio-tab-body"><div className="studio-form-grid cols4"><label>Fornecedor<select value={draft.supplier_id} onChange={e=>set('supplier_id',e.target.value)}><option value="">Nenhum</option>{suppliers.map(s=><option key={text(s.id)} value={text(s.id)}>{text(s.name)}</option>)}</select></label><label>Fornecedor exclusivo<Toggle value={draft.exclusive_supplier} onChange={v=>set('exclusive_supplier',v)}/></label><label>Categoria financeira<input value={draft.financial_category} onChange={e=>set('financial_category',e.target.value)}/></label><label>Local do estoque<input value={draft.stock_location} onChange={e=>set('stock_location',e.target.value)}/></label><label>Fracionado<Toggle value={draft.fractioned} onChange={v=>set('fractioned',v)}/></label><label>Chama quantidade<Toggle value={draft.prompt_quantity} onChange={v=>set('prompt_quantity',v)}/></label><label>Pesável / balança<Toggle value={draft.is_weighable} onChange={v=>{set('is_weighable',v);if(v&&draft.unit==='UN')set('unit','KG')}}/></label><label>Modificadores<Toggle value={draft.modifiers_enabled} onChange={v=>set('modifiers_enabled',v)}/></label><label>Permite desconto<Toggle value={draft.allow_discount} onChange={v=>set('allow_discount',v)}/></label><label>Incide acréscimo<Toggle value={draft.apply_surcharge} onChange={v=>set('apply_surcharge',v)}/></label><label>Autoatendimento<Toggle value={draft.self_service} onChange={v=>set('self_service',v)}/></label><label>Favorito<Toggle value={draft.favorite} onChange={v=>set('favorite',v)}/></label><label>Venda +18<Toggle value={draft.age_restricted} onChange={v=>set('age_restricted',v)}/></label><label>Balança etiquetadora<Toggle value={draft.label_scale} onChange={v=>set('label_scale',v)}/></label><label>Dias de validade<input type="number" min="0" value={draft.shelf_life_days} onChange={e=>set('shelf_life_days',e.target.value)}/></label><label>Setor de produção<input value={draft.production_sector} onChange={e=>set('production_sector',e.target.value)}/></label><label>Modo de produção<select value={draft.production_mode} onChange={e=>set('production_mode',e.target.value)}><option value="stock">Estoque próprio</option><option value="on_demand">Sob demanda</option><option value="batch">Produção em lote</option></select></label><label>Rendimento<input type="number" min="0.000001" step="0.001" value={draft.production_yield} onChange={e=>set('production_yield',e.target.value)}/></label><label>Impressora de produção<input value={draft.production_printer} onChange={e=>set('production_printer',e.target.value)}/></label><label>Imprimir automaticamente<Toggle value={draft.auto_print_production} onChange={v=>set('auto_print_production',v)}/></label><label className="span4">Descrição para produção<textarea rows={3} value={draft.production_description} onChange={e=>set('production_description',e.target.value)}/></label></div><fieldset className="studio-fieldset"><legend>Unidades de compra</legend><button type="button" className="studio-secondary" onClick={()=>setPurchaseUnits(current=>[...current,{unit:'CX',conversion_factor:1,barcode:'',is_default:current.length===0}])}>+ Unidade</button>{purchaseUnits.map((unit,index)=><div className="studio-purchase-row" key={index}><select value={unit.unit} onChange={e=>setPurchaseUnits(c=>c.map((x,i)=>i===index?{...x,unit:e.target.value}:x))}>{units.map(([code,label])=><option key={code} value={code}>{code} — {label}</option>)}</select><input type="number" min="0.000001" step="0.000001" value={unit.conversion_factor} onChange={e=>setPurchaseUnits(c=>c.map((x,i)=>i===index?{...x,conversion_factor:num(e.target.value)}:x))}/><input value={unit.barcode} onChange={e=>setPurchaseUnits(c=>c.map((x,i)=>i===index?{...x,barcode:e.target.value}:x))} placeholder="EAN/GTIN"/><label><input type="checkbox" checked={unit.is_default} onChange={e=>setPurchaseUnits(c=>c.map((x,i)=>({...x,is_default:i===index?e.target.checked:false})))}/> Padrão</label><button type="button" onClick={()=>setPurchaseUnits(c=>c.filter((_,i)=>i!==index))}>Excluir</button></div>)}</fieldset></div>}
      {advancedTab==='fiscal'&&<div className="studio-tab-body"><ProductFiscalEditor value={draft} onChange={(key,value)=>setDraft(current=>({...current,[key]:value}))}/><fieldset className="studio-fieldset"><legend>Modificadores</legend><div className="studio-modifier-grid">{modifiers.map(m=><label key={text(m.id)}><input type="checkbox" checked={modifierIds.includes(text(m.id))} onChange={e=>setModifierIds(c=>e.target.checked?[...c,text(m.id)]:c.filter(id=>id!==text(m.id)))}/><span>{text(m.name)}</span><small>{num(m.price_delta)?money(m.price_delta):'Sem acréscimo'}</small></label>)}</div></fieldset></div>}
      {advancedTab==='stock'&&<div className="studio-tab-body"><div className="studio-stock-grid">{branches.map(branch=>{const stock=stockRows.find(x=>text(x.branch_id)===text(branch.id));return <article key={text(branch.id)}><span>{text(branch.name)}</span><strong>{num(stock?.quantity).toLocaleString('pt-BR',{maximumFractionDigits:3})} {draft.unit}</strong><small>Reservado {num(stock?.reserved).toLocaleString('pt-BR',{maximumFractionDigits:3})} · Disponível {num(stock?.available).toLocaleString('pt-BR',{maximumFractionDigits:3})}</small></article>})}</div>{draft.product_structure==='simple'?<div className="studio-stock-entry"><label>Entrada de estoque<input type="number" min="0" step="0.001" value={draft.stock_to_add} onChange={e=>set('stock_to_add',e.target.value)}/></label><button type="button" className="studio-primary" onClick={addStock}>Registrar entrada</button></div>:<div className="studio-note">Em produtos com grade, a entrada é feita individualmente na tabela de variações.</div>}</div>}
      {advancedTab==='composition'&&<div className="studio-tab-body"><div className="studio-composition-head"><div><strong>Ficha técnica / insumos</strong><span>Custo estimado: {money(compositionCost)}</span></div><button type="button" className="studio-secondary" onClick={()=>{const first=products.find(p=>text(p.id)!==draft.id);if(first)setComposition(c=>[...c,{component_product_id:text(first.id),quantity:1,unit:text(first.unit)||'UN',waste_percent:0,deduct_stock:true}]);else setMessage('Cadastre um insumo antes.')}}>+ Insumo</button></div><div className="studio-composition-table"><table><thead><tr><th>Insumo</th><th>Qtd.</th><th>Un.</th><th>Perda %</th><th>Baixa</th><th>Custo</th><th/></tr></thead><tbody>{composition.length===0?<tr><td colSpan={7} className="studio-empty">Nenhum insumo configurado.</td></tr>:composition.map((item,index)=>{const product=productMap.get(item.component_product_id);const cost=item.quantity*(1+item.waste_percent/100)*num(product?.cost_price);return <tr key={`${item.component_product_id}-${index}`}><td><select value={item.component_product_id} onChange={e=>setComposition(c=>c.map((x,i)=>i===index?{...x,component_product_id:e.target.value,unit:text(productMap.get(e.target.value)?.unit)||x.unit}:x))}>{products.filter(p=>text(p.id)!==draft.id).map(p=><option key={text(p.id)} value={text(p.id)}>{text(p.name)}</option>)}</select></td><td><input type="number" min="0.000001" step="0.000001" value={item.quantity} onChange={e=>setComposition(c=>c.map((x,i)=>i===index?{...x,quantity:num(e.target.value)}:x))}/></td><td><select value={item.unit} onChange={e=>setComposition(c=>c.map((x,i)=>i===index?{...x,unit:e.target.value}:x))}>{units.map(([code])=><option key={code} value={code}>{code}</option>)}</select></td><td><input type="number" min="0" step="0.01" value={item.waste_percent} onChange={e=>setComposition(c=>c.map((x,i)=>i===index?{...x,waste_percent:num(e.target.value)}:x))}/></td><td><input type="checkbox" checked={item.deduct_stock} onChange={e=>setComposition(c=>c.map((x,i)=>i===index?{...x,deduct_stock:e.target.checked}:x))}/></td><td>{money(cost)}</td><td><button type="button" onClick={()=>setComposition(c=>c.filter((_,i)=>i!==index))}>×</button></td></tr>})}</tbody></table></div>{draft.product_structure==='grade'&&<div className="studio-note warning">A grade já está funcional para preço, estoque, EAN, foto e venda. A ficha técnica ainda permanece no produto mestre nesta primeira etapa e não é duplicada automaticamente para cada variação.</div>}</div>}
      {advancedTab==='history'&&<div className="studio-tab-body"><div className="studio-history">{history.length===0?<p>Nenhum histórico disponível.</p>:history.map(h=><article key={text(h.id)}><div><strong>{text(h.description)}</strong><small>{text(h.event_type)}</small></div><time>{new Date(text(h.created_at)).toLocaleString('pt-BR')}</time></article>)}</div></div>}
    </section>
    <footer className="studio-editor-footer"><button type="button" className="studio-secondary" onClick={onClose}>Voltar</button><button type="button" className="studio-primary" disabled={pending} onClick={save}>{pending?'Salvando...':'Salvar produto'}</button></footer>
  </div>;
}

function AttributeEditor({attribute,onName,onAdd,onRemoveValue,onRemove}:{attribute:GradeAttribute;onName:(v:string)=>void;onAdd:(v:string)=>void;onRemoveValue:(v:string)=>void;onRemove:()=>void}){const [value,setValue]=useState('');return <article className="studio-attribute"><div><input value={attribute.name} onChange={e=>onName(e.target.value)} aria-label="Nome do atributo"/><button type="button" onClick={onRemove}>×</button></div><div className="studio-chips">{attribute.values.map(v=><span key={v}>{v}<button type="button" onClick={()=>onRemoveValue(v)}>×</button></span>)}</div><form onSubmit={e=>{e.preventDefault();onAdd(value);setValue('')}}><input value={value} onChange={e=>setValue(e.target.value)} placeholder="Novo valor, ex.: Preto"/><button>Adicionar</button></form></article>}

type BulkState={ncmEnabled:boolean;ncm:string;group_id:string;brand_id:string;tax_situation:string;is_weighable:string};
const emptyBulk=():BulkState=>({ncmEnabled:false,ncm:'',group_id:'__keep__',brand_id:'__keep__',tax_situation:'__keep__',is_weighable:'__keep__'});

export function ProductStudioWorkspace({initialProducts,initialTotal=initialProducts.length,groups,classes,suppliers,modifiers,branches,brands=[],categories=[]}:{initialProducts:Row[];initialTotal?:number;groups:Row[];classes:Row[];suppliers:Row[];modifiers:Row[];branches:Row[];brands?:Row[];categories?:Row[]}){
  const pageSize=10;
  const [products,setProducts]=useState(initialProducts);
  const [total,setTotal]=useState(initialTotal);
  const [search,setSearch]=useState('');
  const [appliedSearch,setAppliedSearch]=useState('');
  const [filters,setFilters]=useState<ProductListFilters>({});
  const [appliedFilters,setAppliedFilters]=useState<ProductListFilters>({});
  const [offset,setOffset]=useState(0);
  const [editing,setEditing]=useState<Row|null|undefined>(undefined);
  const [editorProducts,setEditorProducts]=useState(initialProducts);
  const [selected,setSelected]=useState<Set<string>>(()=>new Set());
  const [bulkOpen,setBulkOpen]=useState(false);
  const [bulk,setBulk]=useState<BulkState>(()=>emptyBulk());
  const [message,setMessage]=useState('');
  const [pending,startTransition]=useTransition();

  const pageIds=products.map(p=>text(p.id)).filter(Boolean);
  const allPageSelected=pageIds.length>0&&pageIds.every(id=>selected.has(id));
  const from=total===0?0:offset+1;
  const to=Math.min(offset+products.length,total);

  const load=async(nextSearch=appliedSearch,nextFilters=appliedFilters,nextOffset=offset)=>{
    const result=await productStudioList(nextSearch,nextFilters,pageSize,nextOffset);
    if(result.ok){setProducts(result.data);setTotal(result.total);setOffset(result.offset);return result.data;}
    setMessage(text(result.error||'Não foi possível atualizar a lista.'));
    return products;
  };

  const refresh=async()=>{await load();};
  const resetSelection=()=>setSelected(new Set());
  const applySearchAndFilters=()=>startTransition(async()=>{
    setMessage('');setAppliedSearch(search);setAppliedFilters(filters);resetSelection();
    await load(search,filters,0);
  });
  const clearFilters=()=>startTransition(async()=>{
    const clean:ProductListFilters={};setSearch('');setFilters(clean);setAppliedSearch('');setAppliedFilters(clean);resetSelection();setMessage('');await load('',clean,0);
  });
  const changePage=(nextOffset:number)=>startTransition(async()=>{resetSelection();await load(appliedSearch,appliedFilters,Math.max(0,nextOffset));});

  const openEditor=(row:Row|null)=>startTransition(async()=>{
    const catalog=await productStudioList(undefined,{},500,0);
    if(catalog.ok)setEditorProducts(catalog.data);else setEditorProducts(products);
    setEditing(row);
  });

  const toggleRow=(id:string)=>setSelected(current=>{const next=new Set(current);if(next.has(id))next.delete(id);else next.add(id);return next;});
  const togglePage=()=>setSelected(current=>{const next=new Set(current);if(allPageSelected)pageIds.forEach(id=>next.delete(id));else pageIds.forEach(id=>next.add(id));return next;});
  const selectAllFiltered=()=>startTransition(async()=>{
    const result=await productStudioFilteredIds(appliedSearch,appliedFilters);
    if(!result.ok)return setMessage(text(result.error||'Não foi possível selecionar todos os produtos filtrados.'));
    setSelected(new Set(result.ids));setMessage(`${result.total} produto(s) filtrado(s) selecionado(s).`);
  });

  const toggleActive=(row:Row)=>startTransition(async()=>{
    const id=text(row.id);const active=row.active===false;
    const result=await productStudioSetActive(id,active);
    if(!result.ok)return setMessage(text(result.error||'Não foi possível alterar o status do produto.'));
    setProducts(current=>current.map(p=>text(p.id)===id?{...p,active,updated_at:new Date().toISOString()}:p));
    setMessage(`${text(row.name)} ${active?'ativado':'desativado'} com sucesso.`);
  });

  const applyBulk=()=>startTransition(async()=>{
    if(selected.size===0)return setMessage('Selecione pelo menos um produto.');
    const patch:Record<string,unknown>={};
    if(bulk.ncmEnabled)patch.ncm=bulk.ncm.replace(/\D/g,'').slice(0,8);
    if(bulk.group_id!=='__keep__')patch.group_id=bulk.group_id;
    if(bulk.brand_id!=='__keep__')patch.brand_id=bulk.brand_id;
    if(bulk.tax_situation!=='__keep__')patch.tax_situation=bulk.tax_situation;
    if(bulk.is_weighable!=='__keep__')patch.is_weighable=bulk.is_weighable==='true';
    if(Object.keys(patch).length===0)return setMessage('Escolha pelo menos um campo para alterar em massa.');
    if(bulk.ncmEnabled&&patch.ncm&&text(patch.ncm).length!==8)return setMessage('O NCM deve possuir 8 dígitos.');
    const result=await productStudioBulkUpdate([...selected],patch);
    if(!result.ok)return setMessage(text(result.error||'Não foi possível aplicar a alteração em massa.'));
    setBulkOpen(false);setBulk(emptyBulk());resetSelection();await load();
    setMessage(`${num(result.selected)} produto(s) alterado(s) em massa com sucesso.`);
  });

  if(editing!==undefined)return <ProductEditor key={editing?text(editing.id):'new'} row={editing} products={editorProducts} groups={groups} classes={classes} suppliers={suppliers} modifiers={modifiers} branches={branches} onClose={()=>setEditing(undefined)} onSaved={refresh}/>;

  return <div className="product-studio-list enhanced-product-list">
    <section className="product-studio-card studio-list-card">
      <div className="studio-list-toolbar">
        <form onSubmit={e=>{e.preventDefault();applySearchAndFilters();}}><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Pesquisar por descrição, SKU, EAN ou código..."/><button type="submit" aria-label="Pesquisar">Buscar</button></form>
        <div><button type="button" className="studio-primary" onClick={()=>openEditor(null)}>+ Novo</button><button type="button" className="studio-secondary" onClick={()=>startTransition(refresh)}>Atualizar</button></div>
      </div>

      <div className="product-filter-panel">
        <label>Categoria<select value={filters.category_id||''} onChange={e=>setFilters(c=>({...c,category_id:e.target.value}))}><option value="">Todas</option>{categories.filter(x=>x.active!==false).map(x=><option key={text(x.id)} value={text(x.id)}>{text(x.name)}</option>)}</select></label>
        <label>Marca<select value={filters.brand_id||''} onChange={e=>setFilters(c=>({...c,brand_id:e.target.value}))}><option value="">Todas</option>{brands.filter(x=>x.active!==false).map(x=><option key={text(x.id)} value={text(x.id)}>{text(x.name)}</option>)}</select></label>
        <label>Grupo<select value={filters.group_id||''} onChange={e=>setFilters(c=>({...c,group_id:e.target.value}))}><option value="">Todos</option>{groups.filter(x=>x.active!==false).map(x=><option key={text(x.id)} value={text(x.id)}>{text(x.name)}</option>)}</select></label>
        <label>NCM<input inputMode="numeric" value={filters.ncm||''} onChange={e=>setFilters(c=>({...c,ncm:e.target.value.replace(/\D/g,'').slice(0,8)}))} placeholder="Ex.: 22021000"/></label>
        <label>Situação tributária<select value={filters.tax_situation||''} onChange={e=>setFilters(c=>({...c,tax_situation:e.target.value}))}><option value="">Todas</option>{taxOptions.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></label>
        <label>Tipo<select value={filters.product_structure||''} onChange={e=>setFilters(c=>({...c,product_structure:e.target.value}))}><option value="">Simples + grade</option><option value="simple">Simples</option><option value="grade">Com grade</option></select></label>
        <label>Status<select value={filters.active||''} onChange={e=>setFilters(c=>({...c,active:e.target.value}))}><option value="">Ativos + inativos</option><option value="true">Ativos</option><option value="false">Inativos</option></select></label>
        <div className="product-filter-actions"><button type="button" className="studio-primary" onClick={applySearchAndFilters}>Filtrar</button><button type="button" className="studio-secondary" onClick={clearFilters}>Limpar</button></div>
      </div>

      {selected.size>0&&<div className="product-selection-bar"><div><strong>{selected.size}</strong><span>produto(s) selecionado(s)</span>{total>selected.size&&<button type="button" onClick={selectAllFiltered}>Selecionar todos os {total} filtrados</button>}</div><div><button type="button" className="studio-secondary" onClick={resetSelection}>Limpar seleção</button><button type="button" className="studio-primary" onClick={()=>setBulkOpen(true)}>Alterar em massa</button></div></div>}
      {message&&<div className="studio-message">{message}</div>}

      <div className="studio-list-table-wrap"><table className="studio-list-table enhanced-product-table"><thead><tr><th className="select-col"><input type="checkbox" checked={allPageSelected} onChange={togglePage} aria-label="Selecionar todos desta página"/></th><th>Ações</th><th>Descrição</th><th>SKU</th><th>Venda</th><th>Estoque</th><th>UN</th><th>Categoria</th><th>Marca</th><th>Grupo</th><th>NCM</th><th>Situação tributária</th><th>Tipo</th><th>Ativo</th></tr></thead><tbody>
        {products.length===0?<tr><td colSpan={14} className="studio-empty">Nenhum produto encontrado.</td></tr>:products.map(p=>{const id=text(p.id);return <tr key={id} className={selected.has(id)?'selected-row':''}><td className="select-col"><input type="checkbox" checked={selected.has(id)} onChange={()=>toggleRow(id)} aria-label={`Selecionar ${text(p.name)}`}/></td><td><button type="button" className="studio-icon-action" onClick={()=>openEditor(p)}>✎</button></td><td><div className="studio-product-name">{p.image_url?<img src={text(p.image_url)} alt=""/>:<span className="studio-no-photo">▦</span>}<div><strong>{text(p.name)}</strong><small>{p.product_structure==='grade'?`${num(p.variant_count)} variações`:`Código ${text(p.product_code)||'—'}`}</small></div></div></td><td>{text(p.sku)||text(p.product_code)||'—'}</td><td><strong className="studio-sale-price">{p.product_structure==='grade'&&p.variant_price_min!=null?`${money(p.variant_price_min)}${num(p.variant_price_max)!==num(p.variant_price_min)?` — ${money(p.variant_price_max)}`:''}`:money(p.sale_price)}</strong></td><td><span className="studio-stock-pill">{num(p.stock).toLocaleString('pt-BR',{maximumFractionDigits:3})}</span></td><td>{text(p.unit)||'UN'}</td><td>{text(p.category_name)||'—'}</td><td>{text(p.brand_name)||'—'}</td><td>{text(p.group_name)||'—'}</td><td>{text(p.ncm)||'—'}</td><td><span className="tax-situation-cell">{taxLabel(p)}</span></td><td><span className={`studio-kind ${p.product_structure==='grade'?'grade':''}`}>{p.product_structure==='grade'?'Grade':'Simples'}</span></td><td><button type="button" className={`studio-active-toggle ${p.active===false?'off':'on'}`} onClick={()=>toggleActive(p)} disabled={pending} aria-pressed={p.active!==false}><i/>{p.active===false?'Inativo':'Ativo'}</button></td></tr>})}
      </tbody></table></div>

      <div className="studio-list-footer enhanced-list-footer"><span>{total} produto(s) • exibindo {from}–{to}</span><div className="product-pagination"><button type="button" disabled={offset===0||pending} onClick={()=>changePage(offset-pageSize)}>← Anterior</button><span>Página {Math.floor(offset/pageSize)+1} de {Math.max(1,Math.ceil(total/pageSize))}</span><button type="button" disabled={offset+pageSize>=total||pending} onClick={()=>changePage(offset+pageSize)}>Próxima →</button></div><span>{pending?'Atualizando...':'Filtros processados no servidor'}</span></div>
    </section>

    {bulkOpen&&<div className="product-bulk-backdrop" onMouseDown={()=>setBulkOpen(false)}><section className="product-bulk-modal" onMouseDown={e=>e.stopPropagation()}><header><div><small>ALTERAÇÃO EM MASSA</small><h2>{selected.size} produto(s) selecionado(s)</h2><p>Somente os campos escolhidos abaixo serão alterados. Os demais dados permanecem como estão.</p></div><button type="button" onClick={()=>setBulkOpen(false)}>×</button></header><div className="product-bulk-grid">
      <label className="bulk-ncm"><span><input type="checkbox" checked={bulk.ncmEnabled} onChange={e=>setBulk(c=>({...c,ncmEnabled:e.target.checked}))}/> Alterar NCM</span><input disabled={!bulk.ncmEnabled} inputMode="numeric" maxLength={8} value={bulk.ncm} onChange={e=>setBulk(c=>({...c,ncm:e.target.value.replace(/\D/g,'').slice(0,8)}))} placeholder="8 dígitos"/></label>
      <label>Grupo<select value={bulk.group_id} onChange={e=>setBulk(c=>({...c,group_id:e.target.value}))}><option value="__keep__">Não alterar</option><option value="">Remover grupo</option>{groups.filter(x=>x.active!==false).map(x=><option key={text(x.id)} value={text(x.id)}>{text(x.name)}</option>)}</select></label>
      <label>Marca<select value={bulk.brand_id} onChange={e=>setBulk(c=>({...c,brand_id:e.target.value}))}><option value="__keep__">Não alterar</option><option value="">Remover marca</option>{brands.filter(x=>x.active!==false).map(x=><option key={text(x.id)} value={text(x.id)}>{text(x.name)}</option>)}</select></label>
      <label>Situação tributária<select value={bulk.tax_situation} onChange={e=>setBulk(c=>({...c,tax_situation:e.target.value}))}><option value="__keep__">Não alterar</option>{taxOptions.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></label>
      <label>Produto pesável<select value={bulk.is_weighable} onChange={e=>setBulk(c=>({...c,is_weighable:e.target.value}))}><option value="__keep__">Não alterar</option><option value="true">Sim, pesável</option><option value="false">Não pesável</option></select></label>
    </div><footer><button type="button" className="studio-secondary" onClick={()=>setBulkOpen(false)}>Cancelar</button><button type="button" className="studio-primary" disabled={pending} onClick={applyBulk}>{pending?'Aplicando...':`Aplicar em ${selected.size} produto(s)`}</button></footer></section></div>}
  </div>;
}
